`,s.jsx(i.p,{children:"The first month of my capstone project is coming to an end, and I can now move on to working on the Echelon AI Class Card now that a branch has been set up for us to develop in. I’m excited to see what the rest of this journey brings and what I’ll learn along the way!"})]})}function W0(o={}){const{wrapper:i}=o.components||{};return i?s.jsx(i,{...o,children:s.jsx(Rh,{...o})}):Rh(o)}const bm=Object.freeze(Object.defineProperty({__proto__:null,default:W0,frontmatter:$0},Symbol.toStringTag,{value:"Module"})),F0={title:"Working on the Echelon Class Card UI",date:"9/7/2025",wordCount:357};function zh(o){const i={em:"em",img:"img",li:"li",p:"p",ul:"ul",...o.components};return s.jsxs(s.Fragment,{children:[s.jsx(i.p,{children:"This week marks the beginning of the second month of my capstone project! Now that the coding environment is set up for us and we’ve learned the foundations of Compose and Kotlin, we can get to actually work on the Echelon app. As I mentioned in previous blog posts, I assigned myself a ticket from the Jira board to work on the UI of the class cards. This week I started creating the composable functions that make up this card."}),`
`,s.jsx(i.p,{children:"After reviewing the design in Zeplin and looking at the ticket requirements, I split up the card into the following components:"}),`
`,s.jsxs(i.ul,{children:[`
`,s.jsxs(i.li,{children:["The thumbnail, which includes the following:",`
